using System.Diagnostics;using System.Net.Http.Headers;using System.Net.Http.Json;using System.Security.Cryptography;using System.Text;using System.Text.Json;
namespace NoaushioUploader;
static class Program {
 public static readonly string Root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Noaushio","CloudUploader");
 [STAThread] static int Main(string[] args){Directory.CreateDirectory(Root);ApplicationConfiguration.Initialize();try{var engine=new UploadEngine();if(args.Length>0){Task task=args[0]=="--upload"&&args.Length>1?engine.Upload(args[1]):engine.Scan();task.GetAwaiter().GetResult();return 0;}using var singleton=new Mutex(true,"Local\\NoaushioCloudUploader",out bool created);if(!created)return 0;Application.Run(new Tray(engine));return 0;}catch(Exception e){Log("启动失败 / Startup failed: "+e.Message);if(args.Length==0)MessageBox.Show("上传程序无法启动，请查看日志\n"+Path.Combine(Root,"uploader.log"));return 1;}}
 public static void Log(string text){try{var p=Path.Combine(Root,"uploader.log");if(File.Exists(p)&&new FileInfo(p).Length>1024*1024)File.Move(p,Path.Combine(Root,"uploader-previous.log"),true);File.AppendAllText(p,DateTimeOffset.Now.ToString("yyyy-MM-dd HH:mm:ss ")+text+Environment.NewLine);}catch{}}
}
sealed class UploadEngine {
 readonly HttpClient http=new(){Timeout=TimeSpan.FromMinutes(4)};readonly string endpoint;public readonly string Folder;bool busy;readonly Dictionary<string,string> scanned=new();
 public UploadEngine(){var config=JsonDocument.Parse(File.ReadAllText(Path.Combine(Program.Root,"config.json")));endpoint=config.RootElement.GetProperty("endpoint").GetString()!.TrimEnd('/');Folder=Path.GetFullPath(config.RootElement.GetProperty("folder").GetString()!);if(!endpoint.StartsWith("https://"))throw new Exception("HTTPS endpoint required");var protectedToken=File.ReadAllBytes(Path.Combine(Program.Root,"upload-token.bin"));var token=Encoding.UTF8.GetString(ProtectedData.Unprotect(protectedToken,null,DataProtectionScope.CurrentUser));http.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",token);}
 public static bool Safe(FileInfo f){return (f.Attributes&(FileAttributes.Hidden|FileAttributes.System|FileAttributes.ReparsePoint))==0&&!f.Name.StartsWith('.')&&!new[]{"desktop.ini","download-server.js"}.Contains(f.Name,StringComparer.OrdinalIgnoreCase)&&!new[]{".key",".pem",".pfx",".p12",".env",".jks",".keystore"}.Contains(f.Extension,StringComparer.OrdinalIgnoreCase)&&f.Length>0&&f.Length<=2L*1024*1024*1024;}
 public async Task Scan(){if(busy)return;busy=true;try{if(!Directory.Exists(Folder))return;foreach(var file in new DirectoryInfo(Folder).EnumerateFiles()){if(!Safe(file)||file.LastWriteTimeUtc>DateTime.UtcNow.AddSeconds(-5))continue;var stamp=file.Length+"/"+file.LastWriteTimeUtc.Ticks;if(scanned.TryGetValue(file.Name,out var old)&&old==stamp)continue;await Upload(file.FullName);scanned[file.Name]=stamp;}}finally{busy=false;}}
 async Task<JsonElement> Request(string route,object body){using var response=await http.PostAsJsonAsync(endpoint+route,body);if(!response.IsSuccessStatusCode)throw new Exception("云端返回 / Cloud HTTP "+(int)response.StatusCode);return (await response.Content.ReadFromJsonAsync<JsonElement>()).Clone();}
 public async Task Upload(string filePath){var file=new FileInfo(filePath);if(!Safe(file))return;using var stream=new FileStream(file.FullName,FileMode.Open,FileAccess.Read,FileShare.Read);string sha=Convert.ToHexString(await SHA256.HashDataAsync(stream)).ToLowerInvariant();stream.Position=0;
  using(var response=await http.GetAsync(endpoint+"/api/files")){response.EnsureSuccessStatusCode();var listing=await response.Content.ReadFromJsonAsync<JsonElement>();foreach(var item in listing.GetProperty("items").EnumerateArray())if(item.GetProperty("name").GetString()==file.Name&&item.GetProperty("sha256").GetString()==sha)return;}
  string type=file.Extension.ToLowerInvariant() switch {".png"=>"image/png",".jpg" or ".jpeg"=>"image/jpeg",".txt"=>"text/plain",".zip" or ".rwmod"=>"application/zip",".apk"=>"application/vnd.android.package-archive",_=>"application/octet-stream"};
  var start=await Request("/api/admin/start",new {name=file.Name,size=file.Length,sha256=sha,type});string key=start.GetProperty("key").GetString()!,uploadId=start.GetProperty("uploadId").GetString()!;var parts=new List<JsonElement>();byte[] buffer=new byte[8*1024*1024];int part=1;Program.Log("开始上传 / Uploading: "+file.Name);
  while(true){int read=0,n;while(read<buffer.Length&&(n=await stream.ReadAsync(buffer.AsMemory(read,buffer.Length-read)))>0)read+=n;if(read==0)break;HttpResponseMessage? result=null;for(int attempt=0;attempt<3;attempt++){using var content=new ByteArrayContent(buffer,0,read);try{result=await http.PutAsync(endpoint+"/api/admin/part?key="+Uri.EscapeDataString(key)+"&uploadId="+Uri.EscapeDataString(uploadId)+"&part="+part,content);if(result.IsSuccessStatusCode)break;result.Dispose();result=null;}catch when(attempt<2){}await Task.Delay(2000*(attempt+1));}if(result==null)throw new Exception("分片上传失败 / Part upload failed");using(result){result.EnsureSuccessStatusCode();parts.Add((await result.Content.ReadFromJsonAsync<JsonElement>()).Clone());}part++;}
  await Request("/api/admin/complete",new {id=start.GetProperty("id").GetString(),key,uploadId,parts,name=file.Name,size=file.Length,sha256=sha,type,platform=file.Extension.Equals(".exe",StringComparison.OrdinalIgnoreCase)?"Windows x64":file.Extension.Equals(".apk",StringComparison.OrdinalIgnoreCase)?"Android":""});Program.Log("上传完成 / Uploaded: "+file.Name);
 }
}
sealed class Tray:ApplicationContext {
 readonly NotifyIcon icon;readonly System.Windows.Forms.Timer timer=new(){Interval=30000};readonly UploadEngine engine;bool paused;
 public Tray(UploadEngine e){engine=e;icon=new NotifyIcon{Icon=SystemIcons.Application,Text="Noaushio 自动上传",Visible=true};var menu=new ContextMenuStrip();menu.Items.Add("立即上传",null,async(_,_)=>await Tick());menu.Items.Add("打开本地文件夹",null,(_,_)=>Process.Start(new ProcessStartInfo(engine.Folder){UseShellExecute=true}));menu.Items.Add("打开下载站",null,(_,_)=>Process.Start(new ProcessStartInfo("https://download.noaushio.uk/"){UseShellExecute=true}));menu.Items.Add("查看日志",null,(_,_)=>Process.Start(new ProcessStartInfo("notepad.exe",Path.Combine(Program.Root,"uploader.log")){UseShellExecute=true}));var pause=menu.Items.Add("暂停上传");pause.Click+=(_,_)=>{paused=!paused;pause.Text=paused?"继续上传":"暂停上传";};menu.Items.Add("退出",null,(_,_)=>ExitThread());icon.ContextMenuStrip=menu;timer.Tick+=async(_,_)=>await Tick();timer.Start();_=Tick();}
 async Task Tick(){if(paused)return;try{icon.Text="Noaushio 正在检查上传";await engine.Scan();icon.Text="Noaushio 自动上传已就绪";}catch(Exception e){Program.Log("稍后重试 / Retry later: "+e.Message);icon.Text="Noaushio 等待网络，稍后重试";}}
 protected override void ExitThreadCore(){timer.Stop();icon.Visible=false;icon.Dispose();base.ExitThreadCore();}
}
